css:
[data-bz-section="awards-gallery"] .bz-block { padding-block: 0 }
[data-bz-section="awards-gallery"] .bz-block + .bz-block { padding-block-start: 0 }
[data-bz-section="awards-gallery"] h2 { margin: 0 0 40px }

/* The award card: a star, the citation, and the body that gave it, set in the
   italic the handoff uses for an attribution everywhere else on the site. */
[data-bz-section="awards-gallery"] .bz-col[data-bz-node^="ag-card-"]::before {
  content: "\2605"; display: block; font-size: 18px; line-height: 1;
  color: var(--accent); margin-bottom: 10px;
}
[data-bz-section="awards-gallery"] [data-bz-node^="ag-card-h"] h3 { font: 800 17px/1.35 var(--font-heading); margin: 0 0 10px }
[data-bz-section="awards-gallery"] [data-bz-node^="ag-card-org"] p { font-size: 13px; line-height: 1.5; color: var(--muted); font-style: italic; margin: 0 }

/* The photo strip sits inside the same band, 48px under the cards. */
[data-bz-section="awards-gallery"] [data-bz-node="ag-gal-head"] { margin-top: 48px }
[data-bz-section="awards-gallery"] [data-bz-node="ag-gal-h"] .bz-eyebrow { margin-bottom: 18px }

/* Five across, as the handoff draws it. A row is a twelve-column grid and five
   does not divide into twelve, so the track list is stated here rather than
   faked with a span. The columns stay real, in-flow columns either way. */
[data-bz-section="awards-gallery"] [data-bz-node="ag-gal"] { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 16px }
[data-bz-section="awards-gallery"] [data-bz-node="ag-gal"] > .bz-col { grid-column: auto }
[data-bz-section="awards-gallery"] [data-bz-node^="ag-gal-img"] { padding-block: 0 }
[data-bz-section="awards-gallery"] [data-bz-node^="ag-gal-img"] img { display: block; width: 100%; height: 100%; aspect-ratio: 4 / 3; object-fit: cover }
[data-bz-section="awards-gallery"] [data-bz-node="ag-note"] { margin-top: 20px }
[data-bz-section="awards-gallery"] [data-bz-node="ag-note"] p { font-size: 14px; line-height: 1.6; color: var(--muted); margin: 0 }

/* The handoff's own two steps: three photos across below 1100, two below 640. */
@media (max-width: 1100px) {
  [data-bz-section="awards-gallery"] [data-bz-node="ag-gal"] { grid-template-columns: repeat(3, minmax(0, 1fr)) }
}
@media (max-width: 640px) {
  [data-bz-section="awards-gallery"] [data-bz-node="ag-gal"] { grid-template-columns: repeat(2, minmax(0, 1fr)) }
}
